import itertools
from pysat.formula import CNF
from pysat.solvers import Glucose3

fixed_edges = [(0,6), (1,10), (3,6), (3,8), (2,7), (0,4), (1,6), (0,8), (1,2), (5,10), (0,3)]

n = 11
# Variable mapping: for each pair (i,j) with i<j, assign a variable index
var = {}
idx = 1
for i in range(n):
    for j in range(i+1, n):
        var[(i,j)] = idx
        idx += 1

cnf = CNF()

# Fixed edges: these variables are True (unit clauses)
for (i,j) in fixed_edges:
    cnf.append([var[(i,j)]])  # must be true

# α(G) <= 4: For any set of 5 vertices, at least one edge must be present.
for S in itertools.combinations(range(n), 5):
    clause = []
    for i in range(5):
        for j in range(i+1, 5):
            u, v = S[i], S[j]
            if u < v:
                clause.append(var[(u,v)])
            else:
                clause.append(var[(v,u)])
    cnf.append(clause)

print(f"CNF has {len(cnf)} clauses")
print(f"Number of variables: {idx-1}")

solver = Glucose3(cnf)
if solver.solve():
    model = solver.get_model()
    print("SAT!")
    # Extract edges
    edges = set(fixed_edges)
    for (i,j), v_idx in var.items():
        if (i,j) not in fixed_edges and model[v_idx-1] > 0:
            edges.add((i,j))
    print(f"Total edges: {len(edges)}")
    print("Edges:", sorted(edges))
else:
    print("UNSAT!")
